#!/bin/sh
# Regenerates openai/ (the skills-only bundle for the OpenAI plugin submission)
# from skills/ and agents/. Rules from developers.openai.com/plugins/guides/submit-claude-plugin:
# keep .claude-plugin/plugin.json with a description, skills/<name>/SKILL.md,
# convert agents to skills, replace Claude-specific wording with "the model",
# drop marketplace.json, .mcp.json and hooks. Do not edit openai/ by hand.
# openai/ is gitignored on purpose: a committed nested .claude-plugin/plugin.json
# makes the claude.ai / Claude desktop marketplace importer reject the plugin.
set -eu
# Every path below is relative to the repo root and every wildcard starts with
# a literal folder, so the script reads only skills/ and agents/ and writes
# only openai/.
cd "$(dirname "$0")/.."
rm -rf openai
mkdir -p openai/.claude-plugin openai/skills

neutral() {
  # Claude Code specifics -> host-neutral wording; then any remaining "Claude" -> "the model".
  sed -e 's#/sparkletree:\([a-z-]*\)#the sparkletree \1 skill#g' \
      -e 's#`sparkletree:\([a-z-]*\)` agent#`\1` skill#g' \
      -e 's#`skills/\([a-z-]*\)`#the `\1` skill#g' \
      -e 's#In Claude Code, `/mcp` shows the server state and offers authentication; `/reload-plugins` reloads plugin servers#In a coding agent, use its MCP status command to re-authenticate the server#g' \
      -e 's#In Claude Code, `/mcp`, pick sparkletree, authenticate. Elsewhere, remove and re-add the connector#Remove and re-add the connector, or use the host'"'"'s MCP re-authentication command#g' \
      -e 's#Ask the user to run `/mcp`, choose sparkletree, and complete the browser sign-in#Ask the user to add the SparkleTree connector in their host and complete the browser sign-in#g' \
      -e 's#Claude Code and other terminal hosts#Terminal hosts#g' \
      -e 's#(Claude.ai, Claude desktop, ChatGPT)#(for example ChatGPT and other MCP Apps hosts)#g' \
      -e 's#Claude Code#the coding agent#g' \
      -e 's#Claude#the model#g'
}

# Model-invocable skills and commands: copy, neutralise, strip Claude-only frontmatter.
for f in skills/*/SKILL.md; do
  mkdir -p "openai/${f%/SKILL.md}"
  neutral < "$f" | sed -e '/^disable-model-invocation:/d' -e '/^argument-hint:/d' -e 's/\$ARGUMENTS/the user'"'"'s request/g' > "openai/$f"
done
for r in skills/*/references/*; do
  [ -f "$r" ] || continue
  mkdir -p "openai/${r%/*}"
  neutral < "$r" > "openai/$r"
done

# Agents become skills: keep name and description, drop agent-only fields, body unchanged.
for a in agents/*.md; do
  name=${a#agents/}; name=${name%.md}
  mkdir -p "openai/skills/$name"
  awk 'BEGIN{fm=0} /^---$/{fm++; print; next} fm==1 && !/^(name|description):/ {next} {print}' "$a" | neutral > "openai/skills/$name/SKILL.md"
done

# Manifest: same identity, no Claude-only component fields.
cat > openai/.claude-plugin/plugin.json <<'JSON'
{
  "name": "sparkletree",
  "displayName": "SparkleTree",
  "version": "0.1.0",
  "description": "Build your brand and web presence, and create, publish and measure SparkleTree campaigns online and on screens, from your AI: skills for the campaign craft, a read-only reviewer and digest procedure, and guidance for the SparkleTree MCP server.",
  "author": {
    "name": "SparkleTree",
    "email": "support@sparkletree.io",
    "url": "https://sparkletree.io"
  },
  "homepage": "https://sparkletree.io",
  "repository": "https://gitlab.com/sparkletree/sparkletree-plugin",
  "license": "MIT",
  "keywords": ["sparkletree", "marketing", "campaigns", "analytics", "mcp", "brand", "video", "signage"]
}
JSON

cat > openai/README.md <<'MD'
# OpenAI skills bundle

Generated by `scripts/build-openai-bundle.sh` from `../skills` and `../agents`. Upload this directory (zipped) in the OpenAI plugin submission portal as a skills-only plugin, or attach it to the "With MCP" submission that points at `https://app.sparkletree.io/api/mcp`. Host-specific wording is replaced with "the model"; commands and agents are folded into skills; hooks, marketplace and MCP config are not included because the portal does not run them.
MD
# Count and check exactly the files written above; no walk over the tree.
n=0; for f in openai/skills/*/SKILL.md; do [ -f "$f" ] && n=$((n + 1)); done
echo "openai/ regenerated: $n skills"
grep -l "Claude" openai/skills/*/SKILL.md openai/skills/*/references/* openai/README.md openai/.claude-plugin/plugin.json 2>/dev/null && { echo "Claude wording remains"; exit 1; } || echo "no Claude wording remains"
